// returns beginning of the current day timestamp
export const getCurrentDayTS = (): number => new Date().setHours(0, 0, 0, 0);

export const getDaysOfUsage = (installDate: number): number => {
  const day = 24 * 60 * 60 * 1000;
  const firstDate = +new Date(getCurrentDayTS());
  const secondDate = +new Date(installDate).setHours(0, 0, 0, 0);

  return Math.round(Math.abs((firstDate - secondDate) / day));
};

const roundValue = (num: number): number => Math.floor(Number(num) / 5);

export const isWithinOffset = (
  ref: number,
  counter: number,
  offset: number
): boolean => {
  const count = roundValue(counter);
  return count >= ref && ref <= count + offset;
};
